FUNCTION handleDeleteProject(request, project_id):
    // REQ-5-016; preconditions: existing active project and persistence available.
    REQUIRE MANAGER or admin OR RETURN 401 or 403; RETURN 404 for invalid or absent id. BEGIN TRANSACTION; IF tickets or active non-creator memberships exist THEN ROLLBACK; RETURN 409. END IF MARK deleted and append audit; COMMIT; RETURN 204.
    // REQ-5-007 and REQ-5-008; non-idempotent, rollback leaves state and audit unchanged.

FUNCTION handleDeleteMembership(request, project_id, membership_id):
    // REQ-5-020; preconditions: matching active membership and persistence available.
    REQUIRE MANAGER or admin OR RETURN 401 or 403; RETURN 404 for invalid, absent, or mismatched ids. BEGIN TRANSACTION; IF final active MANAGER then ROLLBACK; RETURN 409. END IF DEACTIVATE and append audit; COMMIT; RETURN 204.
    // REQ-5-003 and REQ-5-007; non-idempotent and rollback preserves membership permissions.

FUNCTION handleListAuditEvents(request):
    // REQ-5-025; preconditions: persistence available.
    REQUIRE authenticated user or admin OR RETURN 401; VALIDATE ids, event enum, and pagination OR RETURN 400 or 422; unknown positive project or ticket is 404.
    REQUIRE MANAGER for supplied project unless admin OR RETURN 403; READ matching immutable events by id; RETURN 200 page.
    // REQ-5-007. Transaction: none; postcondition: audit and all persistent state remain unchanged on success and error.

FUNCTION handleListTickets(request):
    // REQ-5-021; preconditions: persistence available.
    REQUIRE user or admin OR RETURN 401; REQUIRE admin for creator filter OR RETURN 403; VALIDATE all filters, query, sort cursor, and pagination OR RETURN 400 or 422.
    REQUIRE membership for each requested project or ticket scope OR RETURN 403; unknown positive references are 404. READ AND-matching rows in mandated order; RETURN 200 page.
    // Transaction: none; postcondition: tickets, permissions, and audit remain unchanged on all errors.

FUNCTION handlePatchProject(request, project_id):
    // REQ-5-015; preconditions: JSON, existing project, persistence available.
    REQUIRE MANAGER or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE result OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF duplicate key or deactivation violates REQ-5-008 THEN ROLLBACK; RETURN 409. END IF UPDATE changed fields; append audit only if changed; COMMIT; RETURN 200.
    // REQ-5-007; identical payload is idempotent and rollback preserves relations and audit history.

FUNCTION handlePatchMembership(request, project_id, membership_id):
    // REQ-5-019; preconditions: JSON, matching membership, persistence available.
    REQUIRE MANAGER or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE result OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF removing final active MANAGER THEN ROLLBACK; RETURN 409. END IF UPDATE changed fields and audit only if changed; COMMIT; RETURN 200.
    // REQ-5-003 and REQ-5-007; identical payload idempotent and rollback preserves access control.

FUNCTION handlePatchTicket(request, ticket_id):
    // REQ-5-024; preconditions: JSON, existing ticket, persistence available.
    REQUIRE eligible creator, MANAGER, or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE partial result OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF assignee missing, inactive, wrong project, or VIEWER THEN ROLLBACK; RETURN 404 or 409. END IF UPDATE changed fields and audit only if changed; COMMIT; RETURN 200.
    // REQ-5-006 and REQ-5-007; identical payload idempotent, rollback preserves all state.

FUNCTION handleCreateProject(request):
    // REQ-5-013; preconditions: JSON and persistence available.
    REQUIRE user or admin OR RETURN 401; REQUIRE JSON OR RETURN 415; VALIDATE REQ-5-002 OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF key exists THEN ROLLBACK; RETURN 409. END IF CREATE project, caller MANAGER membership, and audit row; COMMIT; RETURN 201 with Location.
    // REQ-5-003 and REQ-5-007; non-idempotent and rollback preserves all relations.

FUNCTION handleCreateMembership(request, project_id):
    // REQ-5-018; preconditions: JSON, existing project and account, persistence available.
    REQUIRE MANAGER or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE ids and role OR RETURN 400 or 422; unknown project or account is 404.
    BEGIN TRANSACTION; IF membership exists THEN ROLLBACK; RETURN 409. END IF CREATE membership and audit row; COMMIT; RETURN 201 with Location.
    // REQ-5-003 and REQ-5-007; non-idempotent and rollback preserves permissions.

FUNCTION handleCreateTicket(request):
    // REQ-5-022; preconditions: JSON, active project, persistence available.
    REQUIRE CONTRIBUTOR, MANAGER, or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE ticket body OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF project or assignee missing THEN ROLLBACK; RETURN 404; IF assignee role or project mismatches THEN ROLLBACK; RETURN 409. END IF CREATE ticket and audit row; COMMIT; RETURN 201 with Location.
    // REQ-5-006 and REQ-5-007; non-idempotent and rollback preserves all relations.
